/**
 * THE IMAGE FORGE — operator manage surface (run/manage loop, B-1..B-4).
 *
 * The desk's only door to the supervised ComfyUI: the FR-37 workbench card
 * and the Settings section read /status and drive launch/stop/free here.
 * The desk NEVER calls the ComfyUI API itself (NFR-3) — this backend is the
 * engine's sole client.
 *
 * The image serve/list leg (B-23) is the ONLY way generated bytes leave this
 * machine's disk: authenticated, scoped to a lane the calling wallet owns, and
 * resolved through the lane's manifest rather than any caller-supplied path.
 * There is no static mount and no data-URI lane.
 */
import { createReadStream } from 'fs';
import express from 'express';
import { requireAuth } from '../services/auth.js';
import { requireInstallOwner } from '../services/install-owner.js';
import { createLogger } from '../services/logger.js';
import { neumaWorkspace } from '../../core/index.js';
import { verifyLaneOwnership } from '../services/lane-ownership.js';
import { readManifest, resolveImage } from '../services/image-forge/image-store.js';
import { activitySnapshot } from '../services/image-forge/forge-activity.js';
import { readAttempts, READ_CAP } from '../services/image-forge/attempt-log.js';
import {
  recordReview, readReviews, reviewsFor, toReviewRecord, normalizeVerdict, VERDICTS,
} from '../services/image-forge/review-log.js';
import {
  resolveComfyConfig,
  ensureComfyReady,
  stopComfy,
  freeComfy,
  comfySupervisorStatus,
} from '../services/image-forge/comfyui-supervisor.js';

const log = createLogger('ImageForge.Routes');
const router = express.Router();
router.use(requireAuth);

const cfg = () => resolveComfyConfig(process.env);

// The card's poll: state machine word + install truth + named lastError.
router.get('/status', async (req, res) => {
  try {
    res.json(await comfySupervisorStatus(cfg()));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Launch is long (seconds); the card polls /status for progress. Kick the
// boot, give it a short head start, and answer with the honest snapshot —
// a failure that lands later is named in lastError, never a hung "launching".
// Booting, stopping and freeing the engine are the machine's acts — its GPU
// and its processes are the install owner's, at its own desk (ruling, 2026-10-19).
router.post('/launch', requireInstallOwner, async (req, res) => {
  try {
    const config = cfg();
    const boot = ensureComfyReady(config);
    boot.catch((err) => log.warn('launch failed', { err: err.message }));
    await Promise.race([boot, new Promise((r) => setTimeout(r, 1500))]);
    res.json(await comfySupervisorStatus(config));
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

router.post('/stop', requireInstallOwner, async (req, res) => {
  try {
    const result = await stopComfy();
    res.json({ ...(await comfySupervisorStatus(cfg())), result });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// Operator "return VRAM now" — tier-1 by hand, without stopping the engine.
router.post('/free', requireInstallOwner, async (req, res) => {
  try {
    const result = await freeComfy(cfg());
    res.json({ ...result, ...(await comfySupervisorStatus(cfg())) });
  } catch (err) {
    res.status(500).json({ error: err.message });
  }
});

// What the beings are doing on the engine right now — the COMFY viewport's
// activity rail. ComfyUI cannot answer this: it routes every execution event to
// the submitting client_id alone, so an operator watching its canvas sees only
// the queue counter. This is the backend re-broadcasting what its own lane
// socket already receives (see forge-activity.js).
//
// Rig-wide by design, exactly like /status: the engine is one shared resource
// and the operator is its keeper. Metadata only — no bytes, no prompts (a
// prompt is the being's own words; the image ids here still serve through the
// lane-scoped /images/:imageId gate).
router.get('/activity', (req, res) => {
  res.set('Cache-Control', 'no-store');
  res.json(activitySnapshot());
});

// The operator's debugging record: what was actually asked for, verbatim,
// including every refusal. A refused prompt used to leave NO trace anywhere —
// the being's memory held a summary, and the payload was dropped — so the one
// case that most needs evidence produced none (ruling, 2026-08-01).
//
// `?outcome=refused` narrows to the refusals, which is the usual reason to look.
router.get('/attempts', (req, res) => {
  const limit = Math.min(Number(req.query.limit) || READ_CAP, READ_CAP);
  const { entries, total } = readAttempts(READ_CAP);
  const outcome = req.query.outcome ? String(req.query.outcome) : null;
  const filtered = outcome ? entries.filter((e) => e.outcome === outcome) : entries;
  res.set('Cache-Control', 'no-store');
  res.json({ entries: filtered.slice(0, limit), total, returned: Math.min(filtered.length, limit) });
});

// The lane a request may read: the SAME id shape a neuma id and a witness lane
// id both take, validated before it is ever used to build a path.
const LANE_ID = /^[a-zA-Z0-9_-]{1,96}$/;

// impure — resolve + authorize the lane on the request, or answer for it.
const laneFor = async (req, res) => {
  const laneId = String(req.query.laneId || req.query.neumaId || '');
  if (!LANE_ID.test(laneId)) {
    res.status(400).json({ error: 'laneId is required and must be a plain lane id' });
    return null;
  }
  const owned = await verifyLaneOwnership({
    workspace: neumaWorkspace, neumaId: laneId, wallet: req.walletAddress,
  });
  if (!owned.ok) {
    // 'not-owner' and 'missing lane' answer identically: a wallet that does
    // not own a lane learns nothing about whether it exists.
    res.status(403).json({ error: 'not your lane' });
    return null;
  }
  return laneId;
};

// What this lane has generated — metadata only, never bytes.
router.get('/images', async (req, res) => {
  try {
    const laneId = await laneFor(req, res);
    if (!laneId) return;
    res.json({
      images: readManifest(laneId).map(({ imageId, jobId, mime, bytes, createdAt }) => ({
        imageId, jobId, mime, bytes, createdAt, url: `/api/v1/image-forge/images/${imageId}`,
      })),
    });
  } catch (err) {
    log.error('image list failed', { err: err.message });
    res.status(500).json({ error: 'could not read the image manifest' });
  }
});

// The bytes. Manifest-indexed: the id is matched against recorded entries and
// the filename comes from the record, so no caller-supplied string ever
// becomes a path segment.
router.get('/images/:imageId', async (req, res) => {
  try {
    const laneId = await laneFor(req, res);
    if (!laneId) return;
    const found = resolveImage(laneId, String(req.params.imageId || ''));
    if (!found.ok) return res.status(404).json({ error: found.error });
    res.setHeader('Content-Type', found.record.mime);
    res.setHeader('Content-Length', String(found.record.bytes));
    // Generated bytes are private to the lane — never cached by a shared proxy.
    res.setHeader('Cache-Control', 'private, no-store');
    res.setHeader('X-Content-Type-Options', 'nosniff');
    createReadStream(found.path).pipe(res);
  } catch (err) {
    log.error('image serve failed', { err: err.message });
    res.status(500).json({ error: 'could not read the image' });
  }
});

// THE OPERATOR'S EYE — his verdict on an image, recorded BESIDE the being's and
// never over it.
//
// Design note, 2026-08-05: […] Input — which is what this is. His grade rides forward
// as authoritative evidence the being weighs; it does not correct, replace, or
// silence the being's own verdict. The log is append-only, so […] is
// structural rather than a promise the next writer could break.
router.post('/images/:imageId/grade', async (req, res) => {
  try {
    const laneId = await laneFor(req, res);
    if (!laneId) return;
    const imageId = String(req.params.imageId || '');
    const found = resolveImage(laneId, imageId);
    if (!found.ok) return res.status(404).json({ error: found.error });
    const verdict = normalizeVerdict(req.body?.verdict);
    if (!verdict) return res.status(400).json({ error: `verdict must be one of ${VERDICTS.join(', ')}` });
    const record = toReviewRecord({
      at: new Date().toISOString(),
      imageId,
      jobId: found.record.jobId ?? null,
      laneId,
      by: 'operator',
      author: req.walletAddress,
      verdict,
      note: req.body?.note,
    });
    // A 201 over a refused append would tell the operator their judgment was
    // kept when the disk said otherwise — the gallery would show it, the next
    // read would not, and nothing would explain the gap.
    if (!recordReview(record)) return res.status(500).json({ error: 'the grade could not be written to the ledger' });
    res.status(201).json({ review: record });
  } catch (err) {
    log.error('grade write failed', { err: err.message });
    res.status(500).json({ error: 'could not record the grade' });
  }
});

// Every verdict standing on one image — both standings together, newest first,
// joined to the prompt that was actually sent.
//
// The join is the point: a verdict without the ask is unreadable six weeks
// later, and adherence is the objectively checkable stratum of taste. `asked`
// is null when the attempt has scrolled past the log's read window — said
// plainly rather than guessed at.
router.get('/images/:imageId/reviews', async (req, res) => {
  try {
    const laneId = await laneFor(req, res);
    if (!laneId) return;
    const imageId = String(req.params.imageId || '');
    const found = resolveImage(laneId, imageId);
    if (!found.ok) return res.status(404).json({ error: found.error });
    const jobId = found.record.jobId ?? null;
    const asked = jobId ? readAttempts().entries.find((a) => a.jobId === jobId) || null : null;
    res.set('Cache-Control', 'no-store');
    res.json({
      imageId,
      jobId,
      asked: asked && { positive: asked.positive, negative: asked.negative, params: asked.params },
      // Lane-scoped as well as image-scoped: the ownership check above proves
      // the IMAGE is this lane's, not that every row carrying its id is.
      reviews: reviewsFor(readReviews().entries, imageId, laneId),
    });
  } catch (err) {
    log.error('review read failed', { err: err.message });
    res.status(500).json({ error: 'could not read the reviews' });
  }
});

export default router;
